-- Modify "seller_tax_profiles" table
ALTER TABLE "seller_tax_profiles" ADD CONSTRAINT "chk_stp_receipt_auth_pair" CHECK ((receipt_authorized_at IS NULL) = (receipt_consent_version IS NULL)), ADD CONSTRAINT "chk_stp_receipt_basis_pair" CHECK ((receipt_approval_basis_key IS NULL) = (receipt_approval_basis_asset_id IS NULL)), ADD CONSTRAINT "chk_stp_receipt_consent_nonblank" CHECK ((receipt_consent_version IS NULL) OR (length((receipt_consent_version)::text) >= 1)), ADD COLUMN "receipt_authorized_at" timestamptz NULL, ADD COLUMN "receipt_consent_version" character varying(32) NULL, ADD COLUMN "receipt_approval_basis_key" text NULL, ADD COLUMN "receipt_approval_basis_asset_id" bigint NULL;
